corporate_design.toad_component_blueprint:
canvas {
  size: 920px 600px;
  fill: #FDFBF7;
  font-family: "Nunito, sans-serif";
}

>paperWarm = #FDFBF7;
>tangerine = #FF5E36;
>focusBlue = #2A69AC;
>slateDark = #243038;

rect #cardCourse {
  at: center of canvas;
  size: 800px 480px;
  fill: #FFFFFF;
  stroke: #EADFD0;
  stroke-width: 1px;
  radius: 20px;
}

text #kickerClass {
  at: top left of #cardCourse offset 40px 36px;
  content: "KLASSE 8B • MATHEMATIK & GEOMETRIE";
  font-size: 13px;
  font-weight: 700;
  color: >focusBlue;
}

text #lessonTitle {
  at: below #kickerClass offset 12px;
  content: "Der Satz des Pythagoras im Alltag";
  font-size: 32px;
  font-weight: 800;
  color: >slateDark;
}

rect #btnStartLesson {
  at: below #lessonTitle offset 36px;
  size: 220px 52px;
  fill: >tangerine;
  radius: 12px;
}

text #btnText {
  at: center of #btnStartLesson;
  content: "Aufgabe starten ➔";
  font-size: 15px;
  font-weight: 700;
  color: #FFFFFF;
}
